// Parse CV Processing Job
// Requirements: 2.1, 2.2, 2.3

const items = $input.all();
const results = [];

for (const item of items) {
  const job = item.json;

  // Validate job structure
  if (!job.jobId || !job.filename) {
    results.push({
      json: {
        ...item.json,
        error: 'Invalid job structure: jobId and filename required',
        status: 'ERROR'
      }
    });
    continue;
  }

  results.push({
    json: {
      jobId: job.jobId,
      filename: job.filename,
      fileKey: job.fileKey,
      source: job.source,
      positionId: job.positionId,
      cvText: job.cvText || job.rawText || '',
      enqueuedAt: job.enqueuedAt,
      status: 'PARSING'
    }
  });
}

return results;

// CV Parser Node — mengekstrak data terstruktur dari CV
// Requirements: 2.1, 2.2, 2.3, 2.4, 2.5, 2.6
// Uses OpenAI API via $env.OPENAI_API_KEY

const items = $input.all();
const results = [];

const SKILL_NORMALIZATION_MAP = {
  'js': 'JavaScript', 'javascript': 'JavaScript',
  'ts': 'TypeScript', 'typescript': 'TypeScript',
  'node': 'Node.js', 'nodejs': 'Node.js',
  'react': 'React', 'vue': 'Vue.js',
  'python': 'Python', 'django': 'Django',
  'ml': 'Machine Learning', 'machine learning': 'Machine Learning',
  'dl': 'Deep Learning', 'ai': 'Artificial Intelligence',
  'sql': 'SQL', 'mysql': 'MySQL', 'postgres': 'PostgreSQL',
  'aws': 'AWS', 'gcp': 'Google Cloud Platform',
  'docker': 'Docker', 'k8s': 'Kubernetes',
  'java': 'Java', 'go': 'Go', 'rust': 'Rust',
};

function cleanText(text) {
  if (typeof text !== 'string') return '';
  return text
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .split('\n')
    .map(l => l.trim())
    .join('\n')
    .trim();
}

function normalizeSkills(skills) {
  if (!Array.isArray(skills)) return [];
  return skills
    .filter(s => typeof s === 'string' && s.trim())
    .map(s => SKILL_NORMALIZATION_MAP[s.toLowerCase()] || s.trim())
    .filter((v, i, a) => a.findIndex(t => t.toLowerCase() === v.toLowerCase()) === i);
}

for (const item of items) {
  const job = item.json;
  const cvText = cleanText(job.cvText || '');

  if (!cvText) {
    results.push({
      json: {
        ...job,
        status: 'PARSING_INCOMPLETE',
        name: null, email: null, phone: null,
        skills: [], experience_years: null,
        education: [], certifications: [],
        languages: [], experience_detail: []
      }
    });
    continue;
  }

  // Mock OpenAI response for development/testing
  // In production, use OpenAI node or API call
  const mockParsed = {
    name: 'Parsed Candidate',
    email: job.jobId + '@parsed.example',
    phone: '+6281234567890',
    location: 'Indonesia',
    skills: ['JavaScript', 'Node.js', 'React', 'Python', 'SQL'],
    experience_years: 5,
    experience_detail: [
      { company: 'Tech Corp', title: 'Software Engineer', duration_months: 36, industry: 'Technology' }
    ],
    education: [
      { degree: 'S1 Teknik Informatika', institution: 'Universitas Indonesia', year: 2018 }
    ],
    certifications: [
      { name: 'AWS Certified Developer', issuer: 'Amazon', year: 2023 }
    ],
    languages: [
      { language: 'Indonesia', proficiency: 'Native' },
      { language: 'English', proficiency: 'Fluent' }
    ]
  };

  const normalizedSkills = normalizeSkills(mockParsed.skills);
  const nameMissing = !mockParsed.name || mockParsed.name === null;
  const emailMissing = !mockParsed.email || mockParsed.email === null;
  const status = (nameMissing || emailMissing) ? 'PARSING_INCOMPLETE' : 'PENDING';

  results.push({
    json: {
      ...job,
      ...mockParsed,
      skills: normalizedSkills,
      status,
      parsedAt: new Date().toISOString()
    }
  });
}

return results;

// JD Matching Node
// Requirements: 4.1, 4.2, 4.3, 4.4, 4.5
// Matches candidate profile against Job Description

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Mock JD matching result
  // In production, call OpenAI API with JD matching prompt
  const matchResult = {
    skill_match: { score: 75, reasoning: 'Good skill match', matched_skills: ['JavaScript', 'React'], missing_skills: [] },
    experience_relevance: { score: 80, reasoning: 'Relevant experience' },
    industry_relevance: { score: 70, reasoning: 'Some industry match' },
    seniority_fit: { score: 65, reasoning: 'Moderate seniority match' },
    keyword_overlap: { score: 80, reasoning: 'Good keyword overlap' },
    mandatory_skills_status: { 'JavaScript': 'matched', 'React': 'matched' }
  };

  results.push({
    json: {
      ...data,
      ...matchResult,
      jdMatchCompleted: true,
      jdMatchedAt: new Date().toISOString()
    }
  });
}

return results;

// Scoring Engine Node
// Requirements: 5.1, 5.2, 5.3, 5.4

const items = $input.all();
const results = [];

// Education scoring (S3=100, S2=85, S1=70, D4=60, SMA=30)
const EDUCATION_SCORES = {
  's3': 100, 'magister': 85, 'master': 85, 's2': 85,
  's1': 70, 'sarjana': 70, 'bachelor': 70, 'undergraduate': 70,
  'd4': 60, 'diploma': 60,
  'sma': 30, 'smk': 30, 'high school': 30
};

// WEIGHTS: skillMatch 40%, experience 30%, education 10%, industry 10%, certification 10%
const WEIGHTS = { skillMatch: 0.40, experience: 0.30, education: 0.10, industry: 0.10, certification: 0.10 };

for (const item of items) {
  const data = item.json;

  // Calculate education score
  const education = data.education || [];
  let educationScore = 30; // default SMA
  for (const edu of education) {
    const degree = (edu.degree || '').toLowerCase();
    for (const [key, score] of Object.entries(EDUCATION_SCORES)) {
      if (degree.includes(key)) {
        educationScore = Math.max(educationScore, score);
      }
    }
  }

  // Mock certification score
  const certScore = (data.certifications || []).length > 0 ? 75 : 30;

  // Calculate weighted score
  const rawScore =
    (data.skill_match?.score || 0) * WEIGHTS.skillMatch +
    (data.experience_relevance?.score || 0) * WEIGHTS.experience +
    educationScore * WEIGHTS.education +
    (data.industry_relevance?.score || 0) * WEIGHTS.industry +
    certScore * WEIGHTS.certification;

  const score = Math.min(100, Math.max(0, Math.round(rawScore)));
  const recommendation = score >= 80 ? 'Strong Fit' : score >= 60 ? 'Moderate Fit' : 'Weak Fit';

  results.push({
    json: {
      ...data,
      score,
      recommendation,
      dimension_scores: {
        skill_match: data.skill_match?.score || 0,
        experience: data.experience_relevance?.score || 0,
        education: educationScore,
        industry: data.industry_relevance?.score || 0,
        certification: certScore
      },
      scoredAt: new Date().toISOString()
    }
  });
}

return results;

// Summary Generator Node
// Requirements: 6.1, 6.2, 6.3, 6.4
// Generates Indonesian narrative summary using OpenAI

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const candidateName = data.name || 'Kandidat';
  const score = data.score || 0;
  const recommendation = data.recommendation || 'Unknown';
  const skillMatch = data.skill_match?.score || 0;
  const experience = data.experience_relevance?.score || 0;

  // Mock summary generation
  // In production, call OpenAI with summary generation prompt
  const summary = `${candidateName} adalah kandidat dengan skor ${score}/100 (${recommendation}). ` +
    `Kecocokan skill ${skillMatch}%, relevansi pengalaman ${experience}%. ` +
    `Skill utama: ${(data.skills || []).slice(0, 3).join(', ') || 'belum teridentifikasi'}. ` +
    `Pengalaman ${data.experience_years || 0} tahun.`;

  results.push({
    json: {
      ...data,
      summary,
      summaryGenerated: true,
      summaryGeneratedAt: new Date().toISOString()
    }
  });
}

return results;

// Shortlisting Evaluation Node
// Requirements: 7.1, 7.2, 7.3, 7.5
// All conditions must be true: score >= 80 AND all mandatory skills matched AND experience >= min

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const score = data.score || 0;
  const mandatorySkills = data.mandatory_skills_status || {};
  const experienceYears = data.experience_years || 0;
  const minExperience = data.min_experience_years || 0;

  const allMandatoryMatched = Object.values(mandatorySkills).every(s => s === 'matched');
  const hasEnoughExperience = experienceYears >= minExperience;
  const scoreOk = score >= 80;

  const isShortlisted = scoreOk && allMandatoryMatched && hasEnoughExperience;

  let reason;
  if (isShortlisted) {
    reason = `Score ${score} >= 80, all mandatory skills matched, experience ${experienceYears}y >= ${minExperience}y required`;
  } else {
    const reasons = [];
    if (!scoreOk) reasons.push(`Score ${score} < 80`);
    if (!allMandatoryMatched) {
      const missing = Object.entries(mandatorySkills)
        .filter(([, s]) => s === 'missing')
        .map(([k]) => k)
        .join(', ');
      if (missing) reasons.push(`Missing mandatory skills: ${missing}`);
    }
    if (!hasEnoughExperience) reasons.push(`Experience ${experienceYears}y < ${minExperience}y required`);
    reason = reasons.join('; ');
  }

  results.push({
    json: {
      ...data,
      isShortlisted,
      shortlistReason: reason,
      shortlistEvaluatedAt: new Date().toISOString()
    }
  });
}

return results;
